PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS issues_cache(project_id TEXT NOT NULL, number INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,number));
CREATE TABLE IF NOT EXISTS queues(project_id TEXT PRIMARY KEY, running INTEGER NOT NULL DEFAULT 0, stop_after_current INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS queue_items(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, issue_number INTEGER NOT NULL, provider_id TEXT NOT NULL, position INTEGER NOT NULL, state TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, UNIQUE(project_id,issue_number));
CREATE TABLE IF NOT EXISTS executions(id TEXT PRIMARY KEY, item_id TEXT NOT NULL, project_id TEXT NOT NULL, provider_id TEXT NOT NULL, state TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, reason TEXT, before_git TEXT, after_git TEXT, retry_at TEXT, attempt INTEGER NOT NULL, session_id TEXT);
CREATE TABLE IF NOT EXISTS execution_attempts(execution_id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(sequence INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, execution_id TEXT NOT NULL, attempt_id TEXT NOT NULL, timestamp TEXT NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_execution ON events(execution_id, sequence);
CREATE TABLE IF NOT EXISTS worktree_locks(path TEXT PRIMARY KEY, execution_id TEXT NOT NULL, owner_pid INTEGER NOT NULL, acquired_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_usage(provider_id TEXT PRIMARY KEY, detected_at TEXT NOT NULL, reset_at TEXT, retry_after INTEGER, source TEXT NOT NULL, confidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_capabilities(provider_id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS repositories(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS worktrees(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS policies(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT NOT NULL, action TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS github_cache(url TEXT PRIMARY KEY, etag TEXT, data TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(1, strftime('%Y-%m-%dT%H:%M:%fZ','now'));

CREATE TABLE IF NOT EXISTS github_repository_catalog(account TEXT NOT NULL, repository_id TEXT NOT NULL, project_id TEXT NOT NULL, repository TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(account,repository_id));
